mapper.sql:
FROM acc_completion_certificate c
JOIN acc_completion_satisfaction_bundle b ON b.certificate_id=c.id AND b.tenant_id=c.tenant_id AND b.deleted=b'0'
WHERE c.tenant_id=#{query.tenantId} AND c.deleted=b'0'

    AND c.project_id IN #{projectId}
AND 1=0
AND c.project_id=#{query.projectId}
AND c.name LIKE CONCAT('%',#{query.name},'%')
AND c.status=#{query.status}
